function caseExampleMaturity(){
 const available=isDemo()||Boolean(token), rows=available?risks.map(r=>{const controls=selectedControls(r).map(c=>c.id),complete=controls.length&&controls.every(id=>validMaturityRow(maturityState.rows[id]));const avg=k=>controls.reduce((sum,id)=>sum+maturityState.rows[id][k],0)/controls.length;return {id:code(r),name:r.title,count:controls.length,before:complete?avg('before'):null,after:complete?avg('after'):null}}):[];
 return `<section class="case-example-chart" aria-label="Madurez de controles por riesgo"><div class="case-chart-head"><div><span class="walk-eyebrow">Evaluación del proyecto · escala 0–4</span><h3>Madurez de controles por riesgo</h3><p>Comparación calculada con los niveles y evidencias de los controles vinculados al registro.</p></div><span class="case-chart-flag">${isDemo()?'Demostración':token?'Evaluación Oracle':'Sesión requerida'}</span></div><div class="case-chart-legend"><span><i class="case-chart-dot before"></i> Antes</span><span><i class="case-chart-dot after"></i> Después</span></div><div class="case-chart-scale"><span>0</span><span>1</span><span>2</span><span>3</span><span>4</span></div><div class="case-chart-rows">${rows.map(row=>`<div class="case-chart-row"><div class="case-chart-label"><strong>${esc(row.id)}</strong><span>${esc(row.name)}</span><small>${row.count} controles vinculados</small></div><div class="case-chart-bars" aria-label="${esc(row.id)}: ${row.before===null?'evaluación pendiente':'antes '+row.before.toFixed(1)+', después '+row.after.toFixed(1)}"><div class="case-chart-track"><div class="case-chart-bar before case-width-${row.before===null?0:Math.round(row.before/4*100)}"></div><span>${row.before===null?'—':row.before.toFixed(1)}</span></div><div class="case-chart-track"><div class="case-chart-bar after case-width-${row.after===null?0:Math.round(row.after/4*100)}"></div><span>${row.after===null?'—':row.after.toFixed(1)}</span></div></div></div>`).join('')||'<p class="subtle">Conectá la sesión y registrá riesgos para ver su evaluación.</p>'}</div><p class="case-chart-foot">Cada barra requiere que todos los controles relacionados tengan ambos niveles, referencias y revisión. Un valor pendiente no se sustituye por una estimación ficticia.</p><a href="#audit">Abrir evaluación y auditoría →</a></section>`;
}
function caseLocalPanel(){
 const allowed=!isDemo()&&Boolean(token), data=allowed?caseLocalState.data:null;
 const before=data?.captures?.before?parseCaseCapture(data.captures.before.content,'BEFORE'):null;
 const after=data?.captures?.after?parseCaseCapture(data.captures.after.content,'AFTER'):null;
 const pair=compareCaseCaptures(before,after);
 return `<section class="case-live-panel"><div><h3>Conexión y evidencia del laboratorio</h3><p>Consulta la conexión actual con RCONF_APP y lee las capturas del caso guardadas en Oracle, si existen. No ejecuta scripts ni usa privilegios DBA.</p></div><button class="secondary" id="case-load-local" ${!allowed||caseLocalState.loading?'disabled':''}>${caseLocalState.loading?'Consultando…':'Consultar Oracle y capturas'}</button>${!allowed?'<p class="case-live-note">Conectá una sesión de la aplicación en modo Oracle para consultar.</p>':''}${caseLocalState.error&&allowed?`<p class="form-error" role="alert">${esc(caseLocalState.error)}</p>`:''}${data?`<div class="case-live-result"><div><span>Conexión actual</span><strong>${esc(data.account)} · ${esc(data.pdb)}</strong><small>${esc(data.observed_at||'Fecha no disponible')}</small></div><div><span>Captura antes</span><strong>${before?.valid?before.passed+' / 3':'No válida o ausente'}</strong><small>${before?.valid?esc(before.time):'Revisar archivo'}</small></div><div><span>Captura después</span><strong>${after?.valid?after.passed+' / 3':'No válida o ausente'}</strong><small>${after?.valid?esc(after.time):'Revisar archivo'}</small></div></div><p class="case-live-note">${pair.comparable?'Resultados leídos de copias de las capturas SQL*Plus guardadas en Oracle.':'Las capturas no forman una comparación válida.'} La conexión actual y los archivos son comprobaciones distintas; correlacioná la auditoría como DBA.</p><a href="#audit">Abrir gráfica y expediente de pruebas</a>`:''}</section>`;
}
function caseRiskDetails(){
 if(!isDemo()&&!token)return '<div class="notice">Conectá una sesión para consultar los riesgos guardados en Oracle.</div>';
 if(!risks.length)return '<div class="notice">No hay riesgos registrados para mostrar.</div>';
 return `<div class="scenario-risk-grid">${risks.map(r=>`<article><div class="scenario-risk-top"><strong>${esc(code(r))}</strong>${badge(score(r))}</div><h4>${esc(r.title)}</h4><p><strong>Activo:</strong> ${esc(r.asset)}</p><p><strong>Valoración:</strong> probabilidad ${esc(r.probability)} × impacto ${esc(r.impact)} = ${score(r)}. Residual estimado: ${residual(r)}.</p><p><strong>Controles registrados:</strong> ${esc(r.controls)}</p><p><strong>Tratamiento propuesto:</strong> ${esc(r.treatment)}</p><div class="scenario-risk-foot">${esc(r.phase)} · ${esc(r.status)} <button class="inline-button" data-edit="${esc(r.id)}">Ver registro</button></div></article>`).join('')}</div>`;
}
const CASE_TASK_FREQUENCY=['En cada alta o baja y revisión mensual','Por solicitud y revisión trimestral','Configuración inicial y revisión semestral','Al diseñar y al revisar claves o cambios','Al cambiar datos o vistas y revisión periódica','Según política de respaldo y pruebas de restauración','Configuración inicial y revisión periódica','Según avisos del proveedor y ventana aprobada','Ante cambios de red y revisión periódica','Según plazos de retención aprobados','Revisión periódica y ante alertas','Antes de cada clon o exportación'];
const CASE_TASK_SCRIPT=['08_auditor_controls.sql','04_verify_dba.sql','08_auditor_controls.sql','08_auditor_controls.sql','05_verify_runtime.sql','08_auditor_controls.sql','19_audit_correlation.sql','08_auditor_controls.sql','08_auditor_controls.sql','08_auditor_controls.sql','19_audit_correlation.sql','08_auditor_controls.sql'];
function caseLinkedRisks(ids){if(!isDemo()&&!token)return '<span class="subtle">Conectá sesión</span>';const matched=risks.filter(r=>selectedControls(r).some(c=>ids.includes(c.id)));return matched.length?matched.map(r=>`<button class="inline-button case-risk-link" data-edit="${esc(r.id)}">${esc(code(r))}</button>`).join(' '):'<span class="subtle">Sin coincidencia</span>'}
function caseTaskOverview(){const demo=isDemo(),known=demo||Boolean(token),tasks=demo?DBA_TASKS.map((t,i)=>({...t,id:'T'+String(i+1).padStart(2,'0'),frequency:CASE_TASK_FREQUENCY[i],script:CASE_TASK_SCRIPT[i],status:'PENDIENTE'})):caseDbTasks;const count=Array.isArray(tasks)?tasks.length:null;return `<div class="case-work-intro"><div><span class="scenario-label">Plan de trabajo · ${demo?'demostración':'Oracle XEPDB1'}</span><h3>Tareas críticas de administración</h3><p>${demo?'Catálogo de ejemplo para el navegador.':'Catálogo consultado desde la vista RCONF_OWNER.V_DBA_TASKS mediante RCONF_APP.'}</p></div><strong>${count===null?'—':count} <small>tareas</small></strong></div><p class="helper">Las frecuencias son propuestas para el laboratorio, no obligaciones de ISO ni un calendario ya ejecutado. Los riesgos se sugieren por controles compartidos y deben revisarse. Las tareas figuran pendientes hasta documentar y revisar su ejecución.</p>${!known?'<div class="notice">Conectá una sesión para consultar las tareas guardadas en Oracle.</div>':caseDbTasksError&&!demo?`<div class="form-error" role="alert">No se pudo cargar el catálogo de Oracle: ${esc(caseDbTasksError)}</div>`:!tasks?'<p class="subtle">Consultando tareas de Oracle…</p>':`<div class="table-scroll case-work-table"><table><thead><tr><th>Tarea</th><th>Qué hace el DBA</th><th>Frecuencia propuesta</th><th>Riesgos del registro</th><th>Controles</th><th>Revisión</th><th>Evidencia y consulta</th></tr></thead><tbody>${tasks.map(t=>{const ids=t.controls.match(/\d+\.\d+/g)||[],script=t.script;return `<tr><td><strong>${esc(t.id)} · ${esc(t.task)}</strong></td><td>${esc(t.action)}</td><td>${esc(t.frequency)}</td><td>${caseLinkedRisks(ids)}</td><td>${esc(t.controls)}</td><td><span class="pill">${esc(t.status)}</span></td><td>${esc(t.evidence)}<br><button class="inline-button" data-script-open="${esc(script)}">Ver ${esc(script)}</button></td></tr>`}).join('')}</tbody></table></div>`}<p class="subtle">TDE, respaldo, parches y clones requieren validación específica. Consultar catálogo o ver un script no demuestra que la tarea se haya realizado.</p>`}

const CASE_CONTROL_INTENT={'5.12':'Clasificar la información según su sensibilidad.','5.15':'Definir reglas de acceso alineadas con las necesidades del negocio.','5.16':'Administrar el ciclo de vida de las identidades.','5.17':'Proteger la información de autenticación.','5.18':'Asignar, revisar y retirar derechos de acceso.','5.33':'Proteger registros frente a pérdida, alteración y acceso indebido.','8.2':'Restringir y gestionar privilegios elevados.','8.3':'Restringir el acceso a información según autorización.','8.5':'Aplicar mecanismos apropiados de autenticación.','8.10':'Eliminar información cuando corresponda de forma controlada.','8.11':'Aplicar enmascaramiento cuando corresponda.','8.12':'Reducir la divulgación no autorizada de información.','8.13':'Mantener y verificar respaldos acordes con los requisitos.','8.15':'Registrar eventos pertinentes para su revisión.','8.20':'Proteger redes y servicios de red.','5.23':'Gestionar seguridad para servicios en la nube.','8.9':'Gestionar configuraciones de forma controlada.','8.16':'Monitorear actividades y anomalías pertinentes.','8.24':'Aplicar criptografía y proteger sus claves.','8.28':'Considerar seguridad en el desarrollo de software.'};
function caseScriptForControl(id){return ['8.3','8.11'].includes(id)?'05_verify_runtime.sql':['5.15','5.18','8.2'].includes(id)?'04_verify_dba.sql':['8.15','8.16'].includes(id)?'19_audit_correlation.sql':'08_auditor_controls.sql'}
function caseControlMapping(){const required=new Set(REQUIRED_CONTROL_MATRIX.map(m=>m.id));const entries=CONTROLS.filter(c=>caseControlScope==='all'||(caseControlScope==='required'?required.has(c.id):!required.has(c.id)));return `<div class="case-work-intro"><div><span class="scenario-label">Selección orientativa</span><h3>Del control al trabajo en Oracle</h3><p>Los controles se enlazan con los riesgos guardados por coincidencia del identificador; un revisor debe confirmar la relación.</p></div><strong>${entries.length} <small>controles</small></strong></div><div class="case-filter-bar" aria-label="Filtrar controles">${[['all','Todos'],['required','15 de la asignación'],['additional','Complementarios']].map(([key,label])=>`<button type="button" data-case-control-scope="${key}" aria-pressed="${caseControlScope===key}">${esc(label)}</button>`).join('')}</div><p class="subtle">Los resúmenes son orientativos y no sustituyen el texto de las normas ni una declaración de aplicabilidad. Los controles adicionales son propuestas del proyecto.</p><div class="table-scroll case-work-table"><table><thead><tr><th>Control</th><th>Propósito</th><th>Riesgos del registro</th><th>Aplicación propuesta</th><th>Evidencia / consulta</th><th>Tipo orientativo</th></tr></thead><tbody>${entries.map(c=>{const script=caseScriptForControl(c.id);return `<tr><td><strong>${esc(c.id)}</strong><br>${esc(c.title)}<small>${required.has(c.id)?'Requerido':'Complementario'} · ${esc(c.kind)}</small></td><td>${esc(CASE_CONTROL_INTENT[c.id]||c.title)}</td><td>${caseLinkedRisks([c.id])}</td><td>${esc(c.implementation)}</td><td>${esc(c.evidence)}<br><button class="inline-button" data-script-open="${script}">Ver ${script}</button></td><td>${['8.15','8.16'].includes(c.id)?'Detección':'Prevención / gestión'}</td></tr>`}).join('')}</tbody></table></div>`}
const CASE_AUDITOR_CRITERIA={
 '5.12':['Clasificación documentada por activo y dato relevante.',`SELECT table_name, column_name, comments FROM dba_col_comments WHERE owner = 'RCONF_OWNER';`],
 '5.15':['Accesos autorizados y consistentes con la función aprobada.',`SELECT grantee, table_name, privilege FROM dba_tab_privs WHERE owner = 'RCONF_OWNER';`],
 '5.16':['Cada cuenta tiene responsable vigente y revisión de ciclo de vida.',`SELECT username, account_status, profile FROM dba_users WHERE username LIKE 'RCONF_%';`],
 '5.17':['Custodia de secretos y perfiles revisados; los parámetros no prueban por sí solos la rotación.',`SELECT profile, resource_name, limit FROM dba_profiles WHERE resource_type = 'PASSWORD';`],
 '5.18':['Concesiones revisadas y retiradas cuando ya no corresponden.',`SELECT grantee, table_name, privilege FROM dba_tab_privs WHERE owner = 'RCONF_OWNER';`],
 '5.33':['Responsables, retención y protección de registros demostrados.',`SELECT policy_name, entity_name FROM audit_unified_enabled_policies WHERE policy_name LIKE 'RCONF%';`],
 '8.2':['Privilegios de sistema y roles justificables para la función.',`SELECT grantee, privilege FROM dba_sys_privs WHERE grantee = 'RCONF_APP';`],
 '8.3':['Vista autorizada y lectura directa de la tabla base denegada.',`SELECT * FROM rconf_owner.masked_personal;`],
 '8.5':['Estado de cuenta y parámetros de autenticación acordes con la política aprobada.',`SELECT username, account_status, profile FROM dba_users WHERE username = 'RCONF_APP';`],
 '8.10':['Plazos y eliminación verificables, incluidas copias y exportaciones.',`SELECT owner, original_name, droptime FROM dba_recyclebin WHERE owner = 'RCONF_OWNER';`],
 '8.11':['Datos sintéticos ocultos en la vista y tabla original no accesible.',`SELECT * FROM rconf_owner.masked_personal;`],
 '8.12':['Exportaciones y destinos controlados; el conteo de enlaces es solo una señal parcial.',`SELECT owner, COUNT(*) FROM dba_db_links GROUP BY owner;`],
 '8.13':['Acceso y cifrado de copias revisados y recuperación comprobada.',`SELECT status, encrypted, completion_time FROM v$backup_piece;`],
 '8.15':['Eventos correlacionables por cuenta, sesión, sentencia, hora y retorno.',`SELECT event_timestamp, dbusername, action_name, return_code FROM unified_audit_trail;`],
 '8.20':['Reglas de red y protección del canal verificadas en las conexiones pertinentes.',`SELECT network_service_banner FROM v$session_connect_info;`]};
function caseAuditorObservations(){return `<div class="case-work-intro"><div><span class="scenario-label">Revisión externa</span><h3>15 controles observables</h3><p>Qué debe investigar un auditor, qué consulta puede apoyar la revisión y cuál sería un criterio orientativo.</p></div><strong>15 <small>controles</small></strong></div><p class="helper">Las consultas son apoyo parcial. Algunas requieren una sesión DBA autorizada; 8.3 y 8.11 se contrastan con RCONF_APP. La evidencia y el criterio requieren revisión humana.</p><div class="table-scroll case-work-table"><table><thead><tr><th>Control</th><th>Qué observa</th><th>Consulta de referencia</th><th>Criterio propuesto</th><th>Evidencia / script</th></tr></thead><tbody>${REQUIRED_CONTROL_MATRIX.map(m=>{const c=CONTROLS.find(x=>x.id===m.id),criterion=CASE_AUDITOR_CRITERIA[m.id],script=caseScriptForControl(m.id);return `<tr><td><strong>${esc(m.id)}</strong><br>${esc(c?.title||'')}</td><td>${esc(CONTROL_VERIFICATION[m.id]||c?.implementation||'')}</td><td><code class="case-query">${esc(criterion[1])}</code></td><td>${esc(criterion[0])}</td><td>${esc(c?.evidence||'Revisión documental')}<br><button class="inline-button" data-script-open="${script}">Ver ${script}</button></td></tr>`}).join('')}</tbody></table></div><p class="subtle">Los nombres, filas y SQL son de referencia; ejecutar el script correspondiente en la cuenta indicada y conservar el resultado original. Sin evidencia suficiente, el control permanece pendiente o parcial.</p>`}
function caseRecommendedControls(){const chosen=[['5.15','Definir quién necesita acceder a qué información.'],['5.18','Revisar concesiones y retirar accesos innecesarios.'],['8.2','Limitar privilegios de administración y cuentas técnicas.'],['8.3','Exponer vistas autorizadas y bloquear tablas base.'],['8.11','Ocultar el correo cuando la función no lo necesita.'],['8.15','Correlacionar los eventos permitidos y denegados.']];return `<section class="case-recommendations"><div class="scenario-section-heading"><div><span class="scenario-label">Prioridades del escenario</span><h3>Controles recomendados para empezar</h3></div><p>Selección razonada para el caso; no implica que los controles estén implementados o aprobados.</p></div><div class="case-recommendation-grid">${chosen.map(([id,why])=>{const c=CONTROLS.find(x=>x.id===id),script=caseScriptForControl(id);return `<article><div><strong>${esc(id)}</strong><span>${esc(c?.title||'')}</span></div><p>${esc(why)}</p><small>Riesgos asociados por control: ${caseLinkedRisks([id])}</small><p><b>Qué revisar:</b> ${esc(c?.evidence||'Evidencia documentada')}</p><button class="inline-button" data-script-open="${script}">Ver ${script}</button></article>`}).join('')}</div></section>`}
function caseMatrixPanel(){if(!isDemo()&&!token)return '<div class="notice">Conectá una sesión para consultar la matriz de Oracle.</div>';const stage=caseMatrixStage,ref=stage+'Ref',status=stage+'Status';const options=['','Cumple','Parcial','No cumple'];const counts={Cumple:0,Parcial:0,'No cumple':0,Pendiente:0};for(const c of CONTROLS){const row=maturityState.rows[c.id];if(row?.reviewed&&row[ref]?.trim()&&Number.isInteger(row[stage])&&options.includes(row[status])&&row[status])counts[row[status]]++;else counts.Pendiente++}return `<div class="case-work-intro"><div><span class="scenario-label">Evaluación por control</span><h3>Matriz del laboratorio · ${stage==='before'?'Antes':'Después'}</h3><p>Relacioná tarea, riesgo, nivel 0–4, evidencia y estado revisado. Guardá los cambios en Oracle.</p></div><strong>${CONTROLS.length} <small>controles</small></strong></div><div class="case-filter-bar">${[['before','Antes de la evaluación'],['after','Después de la evaluación']].map(([id,label])=>`<button type="button" data-case-matrix-stage="${id}" aria-pressed="${stage===id}">${label}</button>`).join('')}</div><div class="matrix-totals"><span class="matrix-stat pending"><small>Sin evaluación completa</small><b>${counts.Pendiente}</b><em>Pendiente de revisión</em></span><span class="matrix-stat fail"><small>No cumple</small><b>${counts['No cumple']}</b><em>Requiere tratamiento</em></span><span class="matrix-stat partial"><small>Parcial</small><b>${counts.Parcial}</b><em>Avance documentado</em></span><span class="matrix-stat pass"><small>Cumple</small><b>${counts.Cumple}</b><em>Según evaluación revisada</em></span></div><div class="matrix-status-rail" aria-label="Estado por control">${CONTROLS.map(c=>{const row=maturityState.rows[c.id],ok=row?.reviewed&&row[ref]?.trim()&&Number.isInteger(row[stage])&&options.includes(row[status])&&row[status];const statusName=ok?row[status]:'Pendiente';const cls=statusName==='Cumple'?'pass':statusName==='Parcial'?'partial':statusName==='No cumple'?'fail':'pending';return `<span class="${cls}" title="${esc(c.id+': '+statusName)}" aria-label="${esc(c.id+': '+statusName)}"></span>`}).join('')}</div>${maturityState.loadError?`<p class="form-error" role="alert">${esc(maturityState.loadError)}</p>`:''}<p class="helper">El estado lo decide el revisor: solo se contabiliza al registrar nivel, referencia y marcar revisión. El sistema no deduce cumplimiento de las pruebas ni de un número de madurez. Una fila con datos preliminares sigue pendiente si falta el antes o la revisión; las relaciones de riesgo son sugeridas por control compartido.</p><div class="table-scroll case-work-table"><table><thead><tr><th>Tarea relacionada</th><th>Riesgo del registro</th><th>Control</th><th>Nivel 0–4</th><th>Referencia y revisor</th><th>Estado declarado</th><th>Revisión</th></tr></thead><tbody>${CONTROLS.map(c=>{const row=maturityState.rows[c.id]||{},tasks=DBA_TASKS.filter(t=>(t.controls.match(/\d+\.\d+/g)||[]).includes(c.id));return `<tr><td>${tasks.length?tasks.map(t=>esc(t.task)).join('<br>'):'Revisión de seguridad'}</td><td>${caseLinkedRisks([c.id])}</td><td><strong>${esc(c.id)}</strong><small>${esc(c.title)}</small></td><td><div class="matrix-meter" aria-label="${esc(c.id+' nivel '+(row[stage]??'pendiente'))}">${[1,2,3,4].map(i=>`<span class="${Number.isInteger(row[stage])&&row[stage]>=i?'filled':''}"></span>`).join('')}</div><select aria-label="${esc(c.id+' nivel '+stage)}" data-case-matrix-id="${esc(c.id)}" data-case-matrix-field="${stage}"><option value="">Pendiente</option>${[0,1,2,3,4].map(v=>`<option value="${v}" ${row[stage]===v?'selected':''}>${v}</option>`).join('')}</select></td><td><input aria-label="${esc(c.id+' evidencia '+stage)}" maxlength="300" data-case-matrix-id="${esc(c.id)}" data-case-matrix-field="${ref}" value="${esc(row[ref]||'')}" placeholder="Archivo, fecha y revisor"></td><td><select aria-label="${esc(c.id+' estado '+stage)}" data-case-matrix-id="${esc(c.id)}" data-case-matrix-field="${status}">${options.map(v=>`<option value="${esc(v)}" ${(row[status]||'')===v?'selected':''}>${v||'Pendiente'}</option>`).join('')}</select></td><td><label class="case-check"><input type="checkbox" data-case-matrix-id="${esc(c.id)}" data-case-matrix-field="reviewed" ${row.reviewed?'checked':''}> Revisadas ambas etapas</label></td></tr>`}).join('')}</tbody></table></div><p class="subtle">0 sin evidencia; 1 propuesto; 2 parcial; 3 implementado y probado; 4 sostenido y revisado. Los cambios permanecen en memoria hasta que el analista o gestor pulse Guardar en Oracle. También podés exportar el expediente.</p><div class="button-row"><button class="primary" id="case-save-maturity" ${isDemo()||!token||role==='auditor'||maturityState.version===null?'disabled':''}>Guardar matriz en Oracle</button><button class="secondary" id="case-export-matrix">Guardar expediente JSON</button><a href="#audit">Abrir gráfica y cargar expediente</a></div>`}
function caseChangeSummary(){const pair=(!isDemo()&&token)?auditPair('case'):{};const before=pair.before?parseCaseCapture(pair.before.content,'BEFORE'):null,after=pair.after?parseCaseCapture(pair.after.content,'AFTER'):null,comparison=compareCaseCaptures(before,after);if(!comparison.comparable)return `<section class="case-change-summary"><h3>Qué cambió en Oracle</h3><p>Conectá una sesión y cargá las capturas antes y después para mostrar el cambio comprobado.</p></section>`;const explain={RAW_SELECT:'La lectura directa de la tabla pasó de permitida a denegada.',MASKED_SELECT:'La vista pasó de denegada a devolver el correo oculto.',DIRECT_UPDATE:'La actualización directa permaneció denegada en ambas mediciones.'};const show=r=>r.status==='revisar'?'Requiere revisión · '+r.code:r.outcome==='MASKED'?'Permitido · [oculto]':r.outcome==='ALLOWED'?'Permitido':r.outcome==='DENIED'?'Denegado · ORA-'+String(r.code).padStart(5,'0'):r.outcome+' · '+r.code;return `<section class="case-change-summary"><div class="case-change-heading"><div><span class="scenario-label">Capturas originales en Oracle</span><h3>Qué cambió en el ensayo</h3><p>Las mismas tres operaciones se ejecutaron antes y después en XEPDB1. Las salidas se revisan junto con la auditoría.</p></div><div><strong>${before.passed}/3</strong><span>antes</span> → <strong>${after.passed}/3</strong><span>después</span></div></div><div class="case-change-list">${CASE_PROBES.map(([id,label])=>{const a=before.results.find(r=>r.id===id),b=after.results.find(r=>r.id===id);const known=(id==='RAW_SELECT'&&a.status==='fallo'&&b.status==='satisfactoria'&&a.outcome==='ALLOWED')||(id==='MASKED_SELECT'&&a.status==='fallo'&&b.status==='satisfactoria'&&a.outcome==='DENIED')||(id==='DIRECT_UPDATE'&&a.status==='satisfactoria'&&b.status==='satisfactoria');return `<article><h4>${esc(label)}</h4><div><span>Antes <b>${esc(show(a))}</b></span><span>Después <b>${esc(show(b))}</b></span></div><p>${esc(known?explain[id]:'El resultado requiere revisión del auditor.')}</p></article>`}).join('')}</div><p class="subtle">Fuente: copias de las salidas 14 y 16 guardadas en Oracle. La correlación de eventos de auditoría sigue pendiente.</p><a href="#audit">Ver capturas y gráfica completa →</a></section>`}
function caseBatteryPanel(){const stage=caseBatteryStage,phase=stage==='before'?'BEFORE':'AFTER',capture=(!isDemo()&&token)?auditPair('case')[stage]:null,parsed=capture?parseCaseCapture(capture.content,phase):null;const count=parsed?.valid?parsed.passed:null;return `<div class="case-work-intro"><div><span class="scenario-label">Validación técnica</span><h3>Batería de pruebas</h3><p>Una prueba positiva debe funcionar; una negativa debe ser rechazada. Se comparan las mismas tres operaciones del ensayo aislado.</p></div><strong>${parsed?.valid?count+'/3':'—'} <small>satisfactorias</small></strong></div><div class="case-filter-bar">${[['before','Antes de la evaluación'],['after','Después de la evaluación']].map(([id,label])=>`<button type="button" data-case-battery-stage="${id}" aria-pressed="${stage===id}">${label}</button>`).join('')}</div><button class="secondary" id="case-load-local" ${isDemo()||!token||caseLocalState.loading?'disabled':''}>${caseLocalState.loading?'Consultando…':'Consultar capturas locales de Oracle'}</button>${caseLocalState.error?`<p class="form-error" role="alert">${esc(caseLocalState.error)}</p>`:caseLocalState.message?`<p class="notice" role="status">${esc(caseLocalState.message)}</p>`:''}<p class="helper">${parsed?.valid?'Captura de '+esc(parsed.account)+' · '+esc(parsed.pdb)+' · '+esc(parsed.time)+'. Revisar la procedencia y correlacionar con la auditoría DBA.':'Sin captura cargada para esta etapa. Conectá sesión y consultá las capturas, o importalas en Auditoría antes/después.'}</p><div class="table-scroll case-work-table"><table><thead><tr><th>Prueba</th><th>Operación</th><th>Criterio satisfactorio</th><th>Herramienta</th><th>Resultado observado</th></tr></thead><tbody>${CASE_PROBES.map(([id,label],i)=>{const result=parsed?.valid?parsed.results.find(x=>x.id===id):null;return `<tr><td><strong>CASO-${i+1}</strong></td><td>${esc(label)}</td><td>${id==='MASKED_SELECT'?'Vista permitida con [oculto]':'Acceso directo denegado con ORA-00942 o ORA-01031'}</td><td>SQL*Plus · ${stage==='before'?'14_case_before.sql':'16_case_after.sql'}</td><td>${result?esc(result.status+' · '+result.outcome+' · '+result.code):'Pendiente'}</td></tr>`}).join('')}</tbody></table></div><section class="scenario-section"><h3>Plan ampliado de 15 pruebas</h3><p class="subtle">El siguiente plan incluye revisiones y pruebas adicionales. La columna de observación indica antecedentes o pendientes; no se suma al resultado de las tres pruebas anteriores.</p><div class="table-scroll case-work-table"><table><thead><tr><th>ID / tipo</th><th>Procedimiento</th><th>Resultado esperado</th><th>Herramienta</th><th>Observación / pendiente</th></tr></thead><tbody>${AUDIT_TESTS.map(t=>`<tr><td><strong>${esc(t.id)}</strong><small>${esc(t.title)} · ${esc(t.type)}</small></td><td>${esc(t.procedure)}</td><td>${esc(t.expected)}</td><td>${esc(t.tool)}</td><td>${esc(t.observed)}</td></tr>`).join('')}</tbody></table></div></section><a href="#audit">Ver capturas completas y gráfica →</a>`}
function caseDiagnosticPanel(){
 const allowed=!isDemo()&&Boolean(token),file=allowed?caseLocalState.data?.extra?.CURRENT_DIAGNOSTIC:null;
 const d=file?parseCurrentDiagnostic(file.content):null;
 const count=d?.pieces,enc=d?.encrypted;
 const backup=count===null||count===undefined||enc===null||enc===undefined?'Sin datos interpretables':`${count} piezas · ${enc} cifradas`;
 const pass=d?.verifier===null||d?.verifier===undefined?'Sin datos interpretables':d.verifier.toUpperCase()==='NULL'?'Función no configurada':`Función: ${d.verifier}`;
 const patch=d?.patchEmpty===true?'Sin filas en la consulta':d?.patchEmpty===false?'Hay registros para revisar':'Sin datos interpretables';
 return `<section class="panel section-gap diagnostic-panel" id="diagnostico-oracle"><div class="diagnostic-head"><div><span class="section-tag">Oracle XEPDB1 · consulta de solo lectura</span><h2>Diagnóstico del laboratorio</h2><p>Estado observado en una captura guardada en Oracle. No es una medición histórica anterior ni una consulta en vivo.</p></div>${file?'<span class="diagnostic-stamp">SALIDA SQL*PLUS</span>':''}</div>${!allowed?'<div class="notice">Conectá una sesión de la aplicación en modo Oracle para ver el diagnóstico guardado.</div>':!file?`<p class="helper">${esc(caseLocalState.error||'Todavía no se cargó el diagnóstico guardado en Oracle.')}</p><button class="secondary" id="case-refresh-diagnostic" ${caseLocalState.loading?'disabled':''}>Consultar expediente</button>`:`<p class="diagnostic-source"><strong>Fuente:</strong> ${esc(file.name)} · ${esc(d.captured||'Fecha en el TXT')} · Cuenta de captura: SYS</p><div class="diagnostic-grid"><article><span>RESPALDOS · A8.13</span><strong>${esc(backup)}</strong><p>Conteo de piezas visibles y marcadas como cifradas en esta consulta. Revisar vigencia, protección y recuperación.</p></article><article><span>CONTRASEÑAS · A5.17 / A8.5</span><strong>${esc(pass)}</strong><p>Resultado de PASSWORD_VERIFY_FUNCTION para el perfil DEFAULT. Revisar los perfiles y las políticas aplicables.</p></article><article><span>PARCHES · A8.9</span><strong>${esc(patch)}</strong><p>La consulta de DBA_REGISTRY_SQLPATCH por sí sola no determina si la instalación está actualizada.</p></article></div><div class="diagnostic-actions"><button class="secondary" data-case-extra="CURRENT_DIAGNOSTIC">Descargar salida TXT</button><button class="inline-button" data-script-open="22_diagnostico_actual.sql">Ver consulta SQL →</button></div><details class="diagnostic-output"><summary>Mostrar salida SQL*Plus completa</summary><p>El contenido procede de la captura original. Revisá los nombres de cuentas antes de compartirla.</p><pre class="sql-source" tabindex="0">${esc(file.content)}</pre></details><p class="helper">Los hallazgos requieren revisión. Una consulta aislada no demuestra cumplimiento ISO ni certifica cifrado o recuperación.</p>`}</section>`;
}
function caseOriginalFiles(){
 const docs={...(caseLocalState.data?.extra||{}),CASE_BEFORE:caseLocalState.data?.captures?.before,CASE_AFTER:caseLocalState.data?.captures?.after};
 const entries=[
  ['CASE_BEFORE','Aplicación · antes','Tres pruebas originales previas al tratamiento.'],
  ['CASE_AFTER','Aplicación · después','Las mismas tres pruebas tras el cambio de permisos.'],
  ['CASE_DBA_BEFORE','DBA · antes','Permiso original y política del caso; captura anterior al tratamiento.'],
  ['CASE_DBA_AFTER','DBA · después','Permiso posterior y eventos del caso; revisar sentencia, sesión y código de retorno.'],
  ['CURRENT_DIAGNOSTIC','Diagnóstico actual','Consultas de solo lectura del 29 de octubre; no representa un antes histórico.'],
  ['RUNTIME_20261029','Prueba de RCONF_APP','Salida original de 05_verify_runtime.sql con la cuenta RCONF_APP.'],
  ['RISK_INVENTORY_CURRENT','Inventario de riesgos','Salida original de 18_risk_inventory.sql; conteo y niveles de Oracle.'],
   ['DBA_VERIFY_20261029','DBA · 04 grants y rastro','04_verify_dba.sql como SYS en XEPDB1, 29/10/2026 03:04. Grants, roles, PUBLIC y eventos.'],
   ['AUDITOR_CONTROLS_20261029','DBA · 08 revisión de controles','08_auditor_controls.sql, 29/10/2026 03:04. Observaciones de catálogo por control; no acredita Cumple.'],
   ['AUDIT_CORRELATION_20261029','DBA · 19 auditoría','19_audit_correlation.sql, 29/10/2026 03:04. Política y últimos 100 eventos de RCONF_APP.'],
   ['T11_CORRELATION_20261029','DBA · 24 correlación T11','24_correlacion_t11.sql: eventos de la prueba runtime 00:22:58, sesión 1803193294, códigos 0 y 2004.'],
   ['OBS_INVESTIGATION_PDB','DBA · 23 observaciones (PDB)','23_investigacion_observaciones.sql en XEPDB1: piezas RMAN, wallet, perfil DEFAULT y red.'],
   ['OBS_INVESTIGATION_CDB','DBA · 23 observaciones (CDB)','El mismo script en CDB$ROOT: seis piezas (tres de XEPDB1 y tres autobackups) y trabajos RMAN.'],
   ['BACKUP_ACL_20261029','SO · permisos de respaldos','tools/capturar_acl_respaldos.ps1: ACL NTFS del directorio de piezas RMAN.']
 ];
 const selected=entries.find(item=>item[0]===caseEvidenceSelected)||entries[0],file=docs[selected[0]];
 return `<section class="scenario-section evidence-viewer" id="case-evidence-viewer"><div class="scenario-section-heading"><div><span class="scenario-label">Salidas originales · Oracle local</span><h3>TXT de cada prueba</h3></div><p>Elegí una ejecución para mostrar su salida original. Las copias están guardadas en Oracle.</p></div><div class="evidence-browser"><div class="evidence-list" aria-label="Elegir captura">${entries.map(([key,title])=>`<button type="button" data-case-evidence-select="${esc(key)}" aria-pressed="${key===selected[0]}"><strong>${esc(title)}</strong><small>${docs[key]?'TXT disponible':'Pendiente'}</small></button>`).join('')}</div><div class="evidence-content"><div class="evidence-content-head"><div><span class="scenario-label">SALIDA DE SQL*PLUS</span><h4>${esc(selected[1])}</h4><p>${esc(selected[2])}</p></div>${file?`<button class="secondary" data-case-extra="${esc(selected[0])}">Descargar TXT</button>`:''}</div>${file?`<p class="subtle">${esc(file.name)} · ${esc(file.size)} bytes</p><pre class="sql-source" tabindex="0" aria-label="Salida original ${esc(selected[1])}">${esc(file.content)}</pre>`:'<div class="kanban-empty">No hay salida guardada para esta prueba.</div>'}</div></div><p class="helper">Revisá las capturas del DBA antes de compartirlas. El diagnóstico actual no sustituye una captura anterior.</p></section>`;
}
function caseEvidenceOverview(){if(!isDemo()&&!token)return caseLocalPanel();return `${caseLocalPanel()}${caseDiagnosticPanel()}${caseOriginalFiles()}<section class="scenario-section"><div class="scenario-section-heading"><div><span class="scenario-label">Trazabilidad por control</span><h3>Referencias antes y después</h3></div><p>La matriz muestra lo cargado desde Oracle y cualquier cambio local pendiente; cada referencia requiere comprobación.</p></div><div class="table-scroll case-work-table"><table><thead><tr><th>Control</th><th>Niveles antes → después</th><th>Evidencia anterior</th><th>Evidencia posterior</th><th>Consulta relacionada</th></tr></thead><tbody>${CONTROLS.map(c=>{const r=maturityState.rows[c.id]||{},script=caseScriptForControl(c.id);return `<tr><td><strong>${esc(c.id)}</strong><small>${esc(c.title)}</small></td><td>${r.before??'—'} → ${r.after??'—'} / 4</td><td>${esc(r.beforeRef||'Pendiente')}</td><td>${esc(r.afterRef||'Pendiente')}</td><td><button class="inline-button" data-script-open="${script}">Ver ${script}</button></td></tr>`}).join('')}</tbody></table></div><p class="helper">Las referencias son anotaciones; no prueban autenticidad ni cobertura del control. Usá el visor para revisar y conservar el TXT original.</p><a href="#audit">Abrir visor de salidas originales →</a></section><section class="scenario-section"><h3>Secuencia del caso</h3><p>Las cuentas aisladas ya se prepararon en este laboratorio. El ensayo capturó 14 antes, aplicó 15 y capturó 16 después. DBA consulta 17; no repitás los scripts de instalación 11–13 en esta PDB.</p><a href="/documents/11_caso_antes_despues.md" target="_blank" rel="noopener">Abrir guía de scripts y evidencias</a></section>`}
function caseExampleBody(n){
 const note='<p class="case-example-note">Faro Servicios es un escenario académico. Las evidencias y valoraciones del laboratorio deben revisarse por separado antes de concluir.</p>';
 if(n===0)return `<section class="walk-system-intro"><span class="walk-eyebrow">EIF402 · Administración de Bases de Datos · II ciclo 2026</span><h3>R-CONF: seguridad y confidencialidad en Oracle</h3><p>R-CONF es una aplicación académica que ayuda a identificar riesgos de confidencialidad, seleccionar controles ISO/IEC 27001 y 27002:2022, registrar su tratamiento y revisar evidencias con el ciclo PHVA y el principio de mínimo privilegio.</p></section><div class="walk-system-grid"><article><span>01 · Función</span><h3>¿Qué hace el sistema?</h3><p>Registra y clasifica riesgos; relaciona tareas del DBA y controles; muestra recomendaciones para Planificar, Hacer, Verificar y Actuar; y organiza las referencias a pruebas y scripts.</p><a href="#risks">Explorar el registro de riesgos →</a></article><article><span>02 · Ubicación</span><h3>¿Dónde funciona?</h3><p>La página se ejecuta localmente en <strong>127.0.0.1:8000</strong>. El servidor Python consulta Oracle 21c XE mediante la cuenta limitada <strong>RCONF_APP</strong>, configurada para la PDB <strong>XEPDB1</strong>.</p><p>Azure está previsto para más adelante; esta vista corresponde al entorno local.</p><a href="#database">Ver Oracle y scripts →</a></article><article><span>03 · Acceso</span><h3>¿Quién puede usarlo?</h3><p>El analista registra y trata riesgos; el auditor consulta información; el gestor documenta la decisión sobre el riesgo residual. Cada función usa un token de la aplicación.</p><p>Para revisar el catálogo y el ejemplo guiado no necesitás exponer credenciales.</p></article><article><span>04 · Evidencia</span><h3>¿Qué se puede demostrar?</h3><p>En Oracle se verificó que la cuenta de aplicación puede leer vistas autorizadas y recibe errores al acceder a las tablas base. El ensayo aislado antes y después cuenta con capturas locales que deben revisarse.</p><a href="#evidence">Abrir expediente de evidencias →</a></article></div><details class="walk-quick-guide"><summary>Primera vez aquí · guía de un minuto</summary><ol><li>Abrí Registro de riesgos y comprobá los riesgos que están en Oracle.</li><li>Usá los nueve pasos de este caso para explicar el escenario, controles y pruebas.</li><li>En Oracle y scripts consultá la conexión y revisá las instrucciones antes de ejecutarlas.</li><li>Conservá la salida original, relacioná la evidencia con el riesgo y revisá el resultado con el auditor y el gestor.</li></ol></details><div class="walk-section-heading"><span class="walk-eyebrow">Aplicación del ciclo PHVA</span><h3>Del riesgo a la decisión</h3><p>El ejemplo que sigue usa la organización ficticia Faro Servicios para explicar cada etapa.</p></div><div class="walk-phva">${[['P','Planificar','Identificar E01 y valorar 4 × 5.'],['H','Hacer','Revocar tabla y conceder vista en el caso aislado.'],['V','Verificar','Repetir las mismas tres pruebas y revisar auditoría.'],['A','Actuar','Revisor y gestor deciden con evidencia auténtica.']].map(x=>`<div><b>${x[0]}</b><strong>${x[1]}</strong><p>${x[2]}</p></div>`).join('')}</div>${caseRecommendedControls()}${caseChangeSummary()}${caseExampleMaturity()}${note}`;
 if(n===1)return `<p class="case-example-note">La organización y los datos de clientes son ficticios. Las capturas que consultés abajo proceden del laboratorio Oracle local y requieren revisión.</p><div class="scenario-brief"><div><span class="scenario-label">El entorno</span><h3>Faro Servicios y su aplicación de clientes</h3><p>La empresa es ficticia. El laboratorio usa Oracle 21c XE y la PDB XEPDB1 para evaluar si una cuenta de aplicación puede acceder únicamente a la información necesaria.</p><p>El ensayo separado usa <strong>CASE_CLIENTS</strong>, con un único cliente sintético, y <strong>CASE_MASKED</strong>, una vista que oculta el correo. Su información no representa a una persona real.</p></div><div class="scenario-sensitive"><span class="scenario-label">Campo a proteger</span><strong>CASE_CLIENTS.EMAIL</strong><p>El correo sintético representa un dato de contacto restringido. La vista muestra <code>[oculto]</code>; la lectura de la tabla base debe denegarse tras el tratamiento.</p></div></div>${caseLocalPanel()}<section class="scenario-section"><div class="scenario-section-heading"><div><span class="scenario-label">Inventario del ejemplo</span><h3>Qué información se protege</h3></div><p>Niveles propuestos para el caso; deben validarse con el dueño del dato.</p></div><div class="table-scroll"><table><thead><tr><th>Activo / campo</th><th>Clasificación propuesta</th><th>Uso y exposición</th><th>Estado</th></tr></thead><tbody><tr><td><strong>CASE_CLIENTS.EMAIL</strong><br>Correo sintético</td><td>Restringido</td><td>Tabla base; acceso directo solo si existe autorización expresa.</td><td>Parte del ensayo SQL</td></tr><tr><td><strong>CASE_MASKED</strong><br>ID, nombre y correo oculto</td><td>Vista limitada</td><td>Consulta de aplicación con <code>[oculto]</code> en lugar del correo.</td><td>Parte del ensayo SQL</td></tr><tr><td><strong>Credenciales Oracle</strong></td><td>Secreto</td><td>Acceso restringido; no mostrar ni incluir en evidencias.</td><td>Consideración del escenario</td></tr><tr><td><strong>Respaldos y exportaciones</strong></td><td>Restringido</td><td>Comprobar acceso, protección y eliminación según política.</td><td>Revisión pendiente</td></tr></tbody></table></div></section><section class="scenario-section"><div class="scenario-section-heading"><div><span class="scenario-label">Responsabilidades</span><h3>Actores y acceso previsto</h3></div><p>La tabla define el deber esperado; no es un inventario completo de privilegios efectivos.</p></div><div class="table-scroll"><table><thead><tr><th>Actor</th><th>Cuenta o rol</th><th>Necesita</th><th>Debe evitar</th></tr></thead><tbody><tr><td>DBA</td><td>Sesión DBA autorizada</td><td>Administrar instalación y revisar auditoría.</td><td>Usar privilegios para lecturas ajenas a su función.</td></tr><tr><td>Propietario del caso</td><td>RCONF_CASE_OWNER</td><td>Crear los objetos sintéticos y aplicar concesiones del caso.</td><td>Compartir su credencial con la aplicación.</td></tr><tr><td>Aplicación del caso</td><td>RCONF_CASE_APP</td><td>Consultar la vista enmascarada después del tratamiento.</td><td>Leer o modificar la tabla base sin autorización.</td></tr><tr><td>Aplicación R-CONF</td><td>RCONF_APP</td><td>Consultar vistas y operar el registro mediante su paquete.</td><td>Acceder directamente a tablas base.</td></tr><tr><td>Auditor y gestor</td><td>Roles de la aplicación</td><td>Consultar evidencia; el gestor decide el residual.</td><td>Dar por conforme una referencia sin revisión.</td></tr></tbody></table></div></section><section class="scenario-section"><div class="scenario-section-heading"><div><span class="scenario-label">Análisis inicial</span><h3>Situaciones a investigar</h3></div><p>El primer punto se ensayó en la tabla sintética; los demás son hipótesis del caso.</p></div><div class="scenario-findings"><article><b>Lectura directa inicial</b><p>La cuenta aislada recibió SELECT sobre CASE_CLIENTS para medir el antes. Después se revocó y se concedió la vista.</p><small>E01 / E04 · 5.18, 8.3 y 8.11</small></article><article><b>Identidades y secretos</b><p>Cuentas antiguas o credenciales expuestas podrían permitir acceso indebido; requieren inventario y revisión.</p><small>E02 / E03 · 5.16, 5.17 y 8.5</small></article><article><b>Copias y trazabilidad</b><p>Los accesos a respaldos y la correlación del rastro deben verificarse antes de concluir.</p><small>E05 · 8.13, 8.15 y 8.20</small></article></div></section><p class="helper">El ensayo usa cuentas separadas y no modifica los permisos de RCONF_APP. Las capturas requieren revisión del auditor y correlación DBA.</p>`;
 if(n===2)return `<p>El registro conectado muestra los riesgos realmente guardados en Oracle. La clasificación usa probabilidad × impacto; el residual es una estimación, no una reducción demostrada.</p>${!isDemo()&&!token?'<div class="notice">Conectá una sesión de la aplicación para cargar el registro de Oracle.</div>':riskTable(risks)}<section class="scenario-section"><div class="scenario-section-heading"><div><span class="scenario-label">Comparación del registro</span><h3>Riesgo inherente y residual estimado</h3></div><p>Las posiciones reflejan los valores actuales del registro; no representan una medición histórica automática.</p></div>${heatmap()}</section><section class="scenario-section"><div class="scenario-section-heading"><div><span class="scenario-label">Análisis individual</span><h3>Cada riesgo explicado</h3></div><p>Activo, valoración, controles y tratamiento proceden del registro; revisá su pertinencia y evidencia.</p></div>${caseRiskDetails()}</section><details class="scenario-example"><summary>Ver los cinco riesgos del ejemplo ficticio Faro</summary>${note}<div class="table-scroll"><table><thead><tr><th>ID / riesgo</th><th>Activo</th><th>Inherente</th><th>Residual propuesto</th><th>Controles</th></tr></thead><tbody>${CASE_EXAMPLE_RISKS.map(r=>`<tr><td><strong>${r[0]}</strong> · ${esc(r[1])}</td><td>${esc(r[2])}</td><td>${r[3]} × ${r[4]} = ${r[3]*r[4]}</td><td>${r[5]} × ${r[6]} = ${r[5]*r[6]}</td><td>${esc(r[7])}</td></tr>`).join('')}</tbody></table></div></details><a href="#risks">Abrir el registro para editar o revisar riesgos →</a>`;

 if(n===3)return caseTaskOverview();
 if(n===4)return caseControlMapping();
 if(n===5)return caseAuditorObservations();
 if(n===6)return caseMatrixPanel();
 if(n===7)return caseChangeSummary()+caseBatteryPanel();
 return caseChangeSummary()+caseEvidenceOverview();
}
function caseWalkthrough(){return `<section class="panel section-gap case-walkthrough" aria-label="Recorrido del caso de estudio"><div class="walk-header"><div><span class="section-tag">Expediente guiado · laboratorio Oracle</span><h2>Una auditoría de principio a fin</h2><p>Recorré el caso, analizá cada decisión y contrastala con la evidencia del laboratorio.</p></div><span class="walk-count">${caseWalkthroughStep+1} / ${CASE_STEPS.length}</span></div><nav class="walk-tabs" aria-label="Pasos del caso de estudio">${CASE_STEPS.map((name,i)=>`<button type="button" data-case-step="${i}" ${i===caseWalkthroughStep?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${esc(name)}</button>`).join('')}</nav><div class="walk-content"><div class="walk-title"><span>Paso ${caseWalkthroughStep+1}</span><h2>${esc(CASE_STEPS[caseWalkthroughStep])}</h2></div>${caseExampleBody(caseWalkthroughStep)}</div><div class="walk-actions"><button type="button" class="secondary" data-case-step="${caseWalkthroughStep-1}" ${caseWalkthroughStep===0?'disabled':''}>← Anterior</button><span>Paso ${caseWalkthroughStep+1} de ${CASE_STEPS.length}</span><button type="button" class="primary" data-case-step="${caseWalkthroughStep+1}" ${caseWalkthroughStep===CASE_STEPS.length-1?'disabled':''}>Siguiente →</button></div></section>`}
document.addEventListener('click',event=>{const button=event.target.closest('[data-case-step]');if(!button||button.disabled)return;const next=Number(button.dataset.caseStep);if(Number.isInteger(next)&&next>=0&&next<CASE_STEPS.length){caseWalkthroughStep=next;render();document.querySelector('.case-walkthrough')?.scrollIntoView({block:'start'});}});


function caseWorkspace(){return `<div class="case-section-header"><span class="section-tag">Faro Servicios · laboratorio de confidencialidad</span><nav class="case-section-switch" aria-label="Secciones del caso"><button type="button" data-case-section="case" ${caseSection==='case'?'aria-current="page"':''}><strong>Caso de estudio</strong><small>Contexto, riesgo y resultados observados</small></button><button type="button" data-case-section="steps" ${caseSection==='steps'?'aria-current="page"':''}><strong>Recorrido paso a paso</strong><small>Ejemplo guiado en nueve etapas</small></button></nav></div>${caseSection==='case'?caseStudyExpanded()+caseScriptWalkthrough()+caseAuditRoute():caseWalkthrough()}`}
document.addEventListener('click',event=>{const button=event.target.closest('[data-case-section]');if(!button)return;const selected=button.dataset.caseSection;if(!['case','steps'].includes(selected)||selected===caseSection)return;caseSection=selected;render();document.querySelector('.case-section-header')?.scrollIntoView({block:'start'});});

document.addEventListener('click',async event=>{
 if(!event.target.closest('#case-load-local, #case-load-audit, #case-refresh-diagnostic'))return;
 caseLocalState.loading=true;caseLocalState.error='';caseLocalState.message='';render();
 try{
  const data=await api('/api/case-local');caseLocalState.data=data;
  const before=data.captures?.before,after=data.captures?.after;
  if(!before||!after)throw Error('Conexión realizada, pero faltan capturas de antes o después en Oracle.');
  const parsedBefore=parseCaseCapture(before.content,'BEFORE'),parsedAfter=parseCaseCapture(after.content,'AFTER');
  const comparison=compareCaseCaptures(parsedBefore,parsedAfter);
  if(!comparison.comparable)throw Error('Las capturas de Oracle requieren revisión: '+comparison.error);
  const pair=auditPair('case');
  if((!pair.before&&!pair.after)||auditState.files.case===caseLocalState.auditRef){
   auditState.files.case={before,after};caseLocalState.auditRef=auditState.files.case;
   caseLocalState.message='Capturas consultadas en '+data.pdb+': antes '+parsedBefore.passed+'/3 y después '+parsedAfter.passed+'/3. Seleccioná cada etapa para ver sus resultados.';
  }else{
   caseLocalState.message='Oracle respondió correctamente. Se conservaron las capturas que cargaste manualmente; no fueron reemplazadas.';
  }
 }catch(err){caseLocalState.error='No se pudieron consultar las capturas: '+err.message;caseLocalState.data=null}
 finally{caseLocalState.loading=false;if(activePage==='audit'||activePage==='database'||(activePage==='case'&&caseSection==='steps'))render();toast(caseLocalState.error||caseLocalState.message)}
});

document.addEventListener('click',event=>{const b=event.target.closest('[data-case-control-scope]');if(!b)return;const value=b.dataset.caseControlScope;if(!['all','required','additional'].includes(value))return;caseControlScope=value;render();document.querySelector('.case-walkthrough')?.scrollIntoView({block:'start'});});

document.addEventListener('click',event=>{const matrix=event.target.closest('[data-case-matrix-stage]'),battery=event.target.closest('[data-case-battery-stage]');if(matrix||battery){if(matrix)caseMatrixStage=matrix.dataset.caseMatrixStage;if(battery)caseBatteryStage=battery.dataset.caseBatteryStage;render();document.querySelector('.case-walkthrough')?.scrollIntoView({block:'start'});return}if(event.target.closest('#case-export-matrix'))auditTextDownload(JSON.stringify({format:'rconf-audit-v1',exported_at:new Date().toISOString(),notice:'Evaluaciones y referencias requieren revisión.',files:auditState.files,maturity:{target:maturityState.target,rows:maturityState.rows}},null,2),'rconf-auditoria-expediente.json','application/json')});
document.addEventListener('change',event=>{const id=event.target.dataset.caseMatrixId,field=event.target.dataset.caseMatrixField;if(!id||!CONTROLS.some(c=>c.id===id)||!['before','after','beforeRef','afterRef','beforeStatus','afterStatus','reviewed'].includes(field))return;const row=maturityState.rows[id]||{before:null,after:null,beforeRef:'',afterRef:'',block:CONTROL_BLOCKS[id],reviewed:false};row[field]=['before','after'].includes(field)?(event.target.value===''?null:Number(event.target.value)):field==='reviewed'?event.target.checked:event.target.value;maturityState.rows[id]=row;maturityState.dirty=true;if(!['beforeRef','afterRef'].includes(field))render();});

document.addEventListener('input',event=>{const id=event.target.dataset.caseMatrixId,field=event.target.dataset.caseMatrixField;if(!id||!CONTROLS.some(c=>c.id===id)||!['beforeRef','afterRef'].includes(field))return;const row=maturityState.rows[id]||{before:null,after:null,beforeRef:'',afterRef:'',block:CONTROL_BLOCKS[id],reviewed:false};row[field]=event.target.value;maturityState.rows[id]=row;maturityState.dirty=true;});

document.addEventListener('click',async event=>{if(!event.target.closest('#case-save-maturity'))return;if(isDemo()||!token||role==='auditor'||maturityState.version===null){toast('Conectá una sesión de analista o gestor y cargá la matriz de Oracle.');return}const snapshot=JSON.stringify({target:maturityState.target,rows:maturityState.rows});const payload={version:maturityState.version,...JSON.parse(snapshot)};try{const result=await api('/api/maturity',{method:'PUT',body:JSON.stringify(payload)});maturityState.version=result.version;maturityState.dirty=JSON.stringify({target:maturityState.target,rows:maturityState.rows})!==snapshot;toast(maturityState.dirty?'Matriz guardada; hay cambios posteriores pendientes.':'Matriz guardada en Oracle.');render()}catch(err){toast(err.message)}});

document.addEventListener('click',event=>{if(!event.target.closest('[data-open-case-matrix]'))return;caseSection='steps';caseWalkthroughStep=6;if(activePage!=='case')location.hash='case';else render();});

document.addEventListener('click',event=>{const b=event.target.closest('[data-case-extra]');if(!b)return;const key=b.dataset.caseExtra;const file=key==='CASE_BEFORE'?caseLocalState.data?.captures?.before:key==='CASE_AFTER'?caseLocalState.data?.captures?.after:caseLocalState.data?.extra?.[key];if(file)auditTextDownload(file.content,file.name);});

document.addEventListener('click',event=>{const b=event.target.closest('[data-case-evidence-select]');if(!b)return;caseEvidenceSelected=b.dataset.caseEvidenceSelect;render();document.querySelector('[data-case-evidence-select="'+caseEvidenceSelected+'"]')?.focus({preventScroll:true});});
